// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class PersistentSetTest {

	@TempDir
	Path directory;

	@Test
	void clearingOneSetPreservesPendingUpdatesInOtherSets() throws Exception {
		var factory = new PersistentSetFactory<Long>(directory.toFile());
		try {
			var first = factory.createSet("first", LmdbCompatibilityFixtures::unsigned, Varint::readUnsigned);
			var second = factory.createSet("second", LmdbCompatibilityFixtures::unsigned, Varint::readUnsigned);
			first.add(1L);
			assertThat(first).containsExactly(1L);
			second.add(2L);
			second.add(3L);
			first.clear();
			assertThat(first).isEmpty();
			assertThat(second).hasSize(2).containsExactlyInAnyOrder(2L, 3L);
			first.add(4L);
			second.clear();
			assertThat(second).isEmpty();
			assertThat(first).hasSize(1).containsExactly(4L);
			first.clear();
			assertThat(first).isEmpty();
		} finally {
			factory.close();
		}
	}
}
